    {
        return _image;
    }

    private void setImage(String image)
    {
        _image = image;
    }

    public SmartMessageOptionsType getOptionsType()
    {
        return _optionsType;
    }

    private void setOptionsType(SmartMessageOptionsType optionsType)
    {
