    public Mode getMode() {
        return mode;
    }
    public IntBuffer getIndexBuffer() {
        return indexBuffer;
    }
    public void setIndexBuffer(IntBuffer indices) {
        this.indexBuffer = indices;
        recalcQuadQuantity();
    }
    protected void recalcQuadQuantity() {
        if (indexBuffer == null) {
            quadQuantity = 0;
            return;
        }

